// Copies media/tears-of-steel.en.vtt into the app as a module, so the
// captions ship inside the package instead of needing a server.
const fs = require('fs');
const path = require('path');

const source = path.resolve(__dirname, '../../media/tears-of-steel.en.vtt');
const target = path.resolve(__dirname, '../src/captions/tearsOfSteel.ts');

const vtt = fs.readFileSync(source, 'utf8').replace(/[\\`]|\$\{/g, match => `\\${match}`);

fs.writeFileSync(
  target,
  `// Generated by scripts/bundle-captions.js from media/tears-of-steel.en.vtt.\n` +
    `// Tears of Steel subtitles: (CC) Blender Foundation | mango.blender.org\n\n` +
    `export default \`${vtt}\`;\n`,
);
console.log(`Wrote ${path.relative(process.cwd(), target)}`);
